function updateSortOrderHint() {
  const input = $('#edit-sort-order');
  const hint = $('#edit-sort-order-hint');
  if (!input || !hint) return;
  const value = input.value.trim();
  const currentServerId = input.dataset.currentServerId || '';
  const conflict = Array.from(document.querySelectorAll('[data-edit-server]')).find((button) => button.dataset.editServer !== currentServerId && (button.dataset.sortOrder || '') === value);
  const valid = /^[1-9]\d*$/.test(value) && Number(value) >= 1 && Number(value) <= 500;
  hint.classList.toggle('visible', Boolean(valid && conflict));
  hint.textContent = valid && conflict ? `服务器ID ${value} 已存在，保存后会与该服务器互换顺序。` : '';
}

