function formatLastReport(value) {
  if (!value) return '--';
  const diff = Date.now() - Number(value);
  if (diff < 60_000) return '刚刚';
  if (diff < 3_600_000) return `${Math.floor(diff / 60_000)} 分钟前`;
  if (diff < 86_400_000) return `${Math.floor(diff / 3_600_000)} 小时前`;
  return new Date(value).toLocaleDateString('zh-CN');
}

function formatDateTime(value) {
  const n = Number(value || 0);
  if (!Number.isFinite(n) || n <= 0) return '--';
  return new Date(n).toLocaleString('zh-CN', { hour12: false });
}

function formatNullableBytes(value) {
  if (value === null || value === undefined || value === '') return '--';
  return formatBytes(Number(value));
}

function formatPrice(amount, currency, period) {
  if (amount === null || amount === undefined || amount === '') return '价格未设置';
  const n = Number(amount);
  if (!Number.isFinite(n)) return '价格未设置';
  const suffix = period ? `/${period}` : '';
  return currency === 'USD' ? `$${fmt.format(n)} USD${suffix}` : `${fmt.format(n)} 元${suffix}`;
}

function bytesToGb(value) {
  if (!Number.isFinite(value)) return '';
  return Math.round((value / 1024 / 1024 / 1024) * 100) / 100;
}

function bytesToTb(value) {
  if (!Number.isFinite(value)) return '';
  return Math.round((value / 1024 / 1024 / 1024 / 1024) * 100) / 100;
}

function remainingTrafficInput(value) {
  if (!Number.isFinite(value) || value <= 0) return { value: '', unit: 'GB' };
  const tb = value / 1024 / 1024 / 1024 / 1024;
  if (tb >= 1) return { value: bytesToTb(value), unit: 'TB' };
  return { value: bytesToGb(value), unit: 'GB' };
}

function trafficUnitToBytes(value, unit) {
  if (!Number.isFinite(value) || value < 0) return null;
  const base = unit === 'TB' || unit === 'T' ? 1024 * 1024 * 1024 * 1024 : 1024 * 1024 * 1024;
  return Math.round(value * base);
}

async function copyInstallCommand() {
  if (!latestInstallCommand) return;
  const button = $('#copy-install-command');
  const previous = button.textContent;
  try {
    await copyText(latestInstallCommand);
    button.textContent = '已复制';
    showToast(latestCommandKind === 'uninstall' ? '卸载指令已复制' : '安装指令已复制');
    setTimeout(() => { button.textContent = previous; }, 1200);
  } catch (err) {
    showToast('复制失败，请手动选中复制');
  }
}

async function copyText(text) {
  if (navigator.clipboard?.writeText && window.isSecureContext) {
    await navigator.clipboard.writeText(text);
    return;
  }
  const textarea = document.createElement('textarea');
  textarea.value = text;
  textarea.setAttribute('readonly', '');
  textarea.className = 'copy-fallback-textarea';
  document.body.appendChild(textarea);
  textarea.select();
  textarea.setSelectionRange(0, textarea.value.length);
  const ok = document.execCommand('copy');
  textarea.remove();
  if (!ok) throw new Error('copy failed');
}

function showToast(message, type = 'info') {
  let toast = $('#app-toast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'app-toast';
    toast.className = 'app-toast';
    document.body.appendChild(toast);
  }
  toast.textContent = message;
  toast.className = `app-toast ${type}`;
  toast.classList.add('show');
  clearTimeout(showToast.timer);
  showToast.timer = setTimeout(() => toast.classList.remove('show'), 1800);
}

function errorMessage(err) {
  const raw = err?.message || String(err || '未知错误');
  try {
    const parsed = JSON.parse(raw);
    return parsed.message || parsed.error || raw;
  } catch {
    return raw;
  }
}

function renderOverview(data) {
  const downSpeed = sum(data.servers, (s) => s.net.inBps);
  const upSpeed = sum(data.servers, (s) => s.net.outBps);
  const servers = filterServersByStatus(data.servers || []);
  $('#nav-title').textContent = data.title || '服务器监控面板';
  setText('total-nodes', data.totals.total);
  setText('online-nodes', data.totals.online);
  setText('offline-nodes', data.totals.offline);
  setText('total-nodes-mobile', data.totals.total);
  setText('online-nodes-mobile', data.totals.online);
  setText('offline-nodes-mobile', data.totals.offline);
  setText('current-download-speed', formatBps(downSpeed));
  setText('current-upload-speed', formatBps(upSpeed));
  setText('current-download-speed-mobile', formatBps(downSpeed));
  setText('current-upload-speed-mobile', formatBps(upSpeed));
  setText('total-download', formatBytes(data.totals.netInTotal));
  setText('total-upload', formatBytes(data.totals.netOutTotal));
  setText('total-download-mobile', formatBytes(data.totals.netInTotal));
  setText('total-upload-mobile', formatBytes(data.totals.netOutTotal));
  updateServerFilterButtons();
  renderServerGridStable(servers, data.servers || []);
}

function renderServerGridStable(servers, allServers) {
  const grid = $('#server-grid');
  if (!servers.length) {
    grid.innerHTML = emptyServerListMessage(allServers);
    return;
  }
  const currentIds = Array.from(grid.querySelectorAll('.server-card')).map((card) => card.dataset.sid || '');
  const nextIds = servers.map((server) => String(server.id || ''));
  const canPatch = currentIds.length === nextIds.length && currentIds.every((id, index) => id === nextIds[index]);
  if (!canPatch) {
    grid.innerHTML = servers.map(renderServerCard).join('') || emptyServerListMessage(allServers);
    return;
  }
  for (const server of servers) updateServerCardLive(server);
}

function updateServerCardLive(server) {
  const card = document.querySelector(`.server-card[data-sid="${cssEscape(server.id)}"]`);
  if (!card) return;
  const location = server.country || server.location || 'UNKNOWN';
  const country = countryCode(location);
  if (card.dataset.country !== country) {
    const stack = card.querySelector('.server-icon-stack');
    if (stack) stack.innerHTML = flagIcon(location);
    card.dataset.country = country;
  }
  const offline = !server.online;
  card.classList.toggle('offline', offline);
  card.classList.toggle('online', !offline);
  card.href = `#server/${encodeURIComponent(serverRouteToken(server.id))}`;
  const name = card.querySelector('.server-name');
  if (name) {
    name.textContent = server.name || server.id || '';
    name.title = server.name || server.id || '';
    name.classList.toggle('text-gray-300', offline);
    name.classList.toggle('text-gray-100', !offline);
  }
  const price = card.querySelector('.server-price-label');
  if (price) price.textContent = formatPrice(server.priceAmount, server.priceCurrency, server.pricePeriod);
  const titleExpiry = card.querySelector('.server-title-expiry');
  if (titleExpiry) titleExpiry.outerHTML = expiryBar(expiryUsage(server.startedAt, server.expiresAt), 'server-title-expiry');
  const status = card.querySelector('.server-card-status-pill');
  if (status) {
    const statusText = status.querySelector('.server-card-status-text');
    const statusIcon = status.querySelector('.server-card-status-icon');
    const statusDot = status.querySelector('.server-status-dot');
    const offlineNow = !server.online;
    const nextText = offlineNow ? `离线 ${formatOfflineDuration(server.lastReportAt)}` : `在线 ${formatUptimeDays(server.uptimeSeconds)}`;
    status.title = nextText;
    status.dataset.online = offlineNow ? '0' : '1';
    if (statusIcon) statusIcon.textContent = offlineNow ? 'history' : 'schedule';
    if (statusText) {
      statusText.textContent = nextText;
      statusText.title = nextText;
    }
    if (statusDot) {
      statusDot.classList.toggle('status-dot-online', !offlineNow);
      statusDot.classList.toggle('status-dot-offline', offlineNow);
    }
  }
  const metrics = card.querySelector('.server-card-metrics');
  if (metrics) metrics.innerHTML = serverCardMetrics(server);
}


function filterServersByStatus(servers) {
  if (serverStatusFilter === 'online') return servers.filter((server) => server.online);
  if (serverStatusFilter === 'offline') return servers.filter((server) => !server.online);
  return servers;
}

function emptyServerListMessage(allServers) {
  const text = allServers.length
    ? (serverStatusFilter === 'online' ? '暂无在线服务器。' : '暂无离线服务器。')
    : '暂无服务器。部署 Agent 后会自动出现服务器卡片。';
  return `<div class="card rounded-lg border border-gray-700/50 p-6 text-center text-gray-400">${escapeHtml(text)}</div>`;
}

function handleServerStatusFilterClick(event) {
  const button = event.target.closest('[data-server-filter]');
  if (!button) return;
  serverStatusFilter = button.dataset.serverFilter || 'all';
  if (overview) renderOverview(overview);
}

function updateServerFilterButtons() {
  document.querySelectorAll('[data-server-filter]').forEach((button) => {
    const active = (button.dataset.serverFilter || 'all') === serverStatusFilter;
    button.classList.toggle('active', active);
    button.setAttribute('aria-pressed', active ? 'true' : 'false');
  });
}

function renderClock() {
  setText('updated-at', new Date().toLocaleTimeString('zh-CN', { hour12: false }));
  renderAdminPanelUptime();
}

function renderAdminPanelUptime() {
  if (!adminPanelStartedAt) return setText('admin-panel-uptime', '--');
  const elapsed = Math.max(0, Math.floor((Date.now() - adminPanelStartedAt) / 1000));
  setText('admin-panel-uptime', formatCompactDuration(elapsed));
}

function formatCompactDuration(seconds) {
  let n = Number(seconds || 0);
  const days = Math.floor(n / 86400); n %= 86400;
  const hours = Math.floor(n / 3600); n %= 3600;
  const minutes = Math.floor(n / 60);
  if (days) return `${days}天 ${hours}小时`;
  if (hours) return `${hours}小时 ${minutes}分钟`;
  return `${minutes}分钟`;
}

function renderServerCard(server) {
  const location = server.country || server.location || 'UNKNOWN';
  const country = countryCode(location);
  const offline = !server.online;
  return `
    <a class="server-card card-border card-hover card-padding blur-enabled ${offline ? 'offline' : 'online'}" data-sid="${escapeHtml(server.id)}" data-country="${escapeHtml(country)}" href="#server/${encodeURIComponent(serverRouteToken(server.id))}">
      <div class="server-card-inner p-1">
        <div class="server-card-handle flex items-start justify-between mb-3 group">
          <div class="server-title-left min-w-0">
            <div class="server-name-row">
              <span class="server-icon-stack">
                ${flagIcon(location)}
              </span>
              <div class="server-title-text min-w-0">
                <h3 class="server-name font-medium ${offline ? 'text-gray-300' : 'text-gray-100'} truncate" title="${escapeHtml(server.name)}">${escapeHtml(server.name)}</h3>
                <div class="server-price-label">${escapeHtml(formatPrice(server.priceAmount, server.priceCurrency, server.pricePeriod))}</div>
                ${expiryBar(expiryUsage(server.startedAt, server.expiresAt), 'server-title-expiry')}
              </div>
            </div>
          </div>
          ${serverStatusPill(server)}
        </div>
        <div class="server-card-metrics space-y-4">${serverCardMetrics(server)}</div>
      </div>
    </a>`;
}

function serverStatusPill(server) {
  const offline = !server.online;
  const statusText = offline ? `离线 ${formatOfflineDuration(server.lastReportAt)}` : `在线 ${formatUptimeDays(server.uptimeSeconds)}`;
  const statusIcon = offline ? 'history' : 'schedule';
  return `<div class="server-card-status-pill" data-online="${offline ? '0' : '1'}" style="--pulse-delay:${statusPulseDelay(server.id)}s" title="${escapeHtml(statusText)}">
    <i class="material-icons md-14 server-card-status-icon">${statusIcon}</i>
    <span class="server-card-status-text">${escapeHtml(statusText)}</span>
    <span class="${server.online ? 'status-dot-online' : 'status-dot-offline'} server-status-dot" title="${server.online ? '在线' : '离线'}"></span>
  </div>`;
}

function statusPulseDelay(seed) {
  let hash = 0;
  const text = String(seed || '');
  for (let i = 0; i < text.length; i += 1) {
    hash = (hash * 31 + text.charCodeAt(i)) >>> 0;
  }
  const phase = (hash % 1450) / 1000;
  return `-${phase.toFixed(3)}`;
}

function serverCardMetrics(server) {
  const trafficUsage = trafficQuotaUsage(server);
  const cycle = server.cycleTraffic || {};
  return `
    <div class="compact-metric-grid compact-metric-grid-three">
      ${barMetric('memory', 'CPU', pct(server.cpu.percent), server.cpu.percent, 'cpu')}
      ${barMetric('dns', '内存', pct(server.memory.percent), server.memory.percent, 'mem')}
      ${barMetric('storage', '磁盘', pct(server.disk.percent), server.disk.percent, 'disk')}
    </div>
    ${trafficQuotaBar(trafficUsage)}
    <div class="server-traffic-grid server-traffic-grid-three text-sm">
      <div class="server-traffic-block"><div class="server-traffic-label">实时速度</div><div class="server-traffic-line text-gray-400"><i class="material-icons md-14 text-green-500/70">arrow_downward</i><span class="traffic-speed">${formatBps(server.net.inBps)}</span></div><div class="server-traffic-line text-gray-400"><i class="material-icons md-14 text-blue-500/70">arrow_upward</i><span class="traffic-speed">${formatBps(server.net.outBps)}</span></div></div>
      <div class="server-traffic-block"><div class="server-traffic-label">周期内流量</div><div class="server-traffic-line text-gray-400"><i class="material-icons md-14 text-green-500/70">arrow_downward</i><span class="traffic-total">${formatBytes(cycle.usedIn || 0)}</span></div><div class="server-traffic-line text-gray-400"><i class="material-icons md-14 text-blue-500/70">arrow_upward</i><span class="traffic-total">${formatBytes(cycle.usedOut || 0)}</span></div></div>
      <div class="server-traffic-block server-boot-traffic-block"><div class="server-traffic-label">开机总流量</div><div class="server-traffic-line text-gray-400"><i class="material-icons md-14 text-green-500/70">arrow_downward</i><span class="traffic-total">${formatBytes(server.net.totalIn)}</span></div><div class="server-traffic-line text-gray-400"><i class="material-icons md-14 text-blue-500/70">arrow_upward</i><span class="traffic-total">${formatBytes(server.net.totalOut)}</span></div></div>
    </div>
    <div class="server-connection-row text-sm text-gray-400">
      <div class="server-connection-item"><i class="material-icons md-14">settings_ethernet</i><span>TCP ${safeCount(server.connections?.tcp)}</span></div>
      <div class="server-connection-item"><i class="material-icons md-14">lan</i><span>UDP ${safeCount(server.connections?.udp)}</span></div>
    </div>`;
}

function safeCount(value) {
  const number = Number(value);
  return Number.isFinite(number) ? Math.max(0, Math.trunc(number)) : 0;
}

function serverRouteToken(serverId) {
  const list = overview?.servers || [];
  const index = list.findIndex((server) => String(server.id || '') === String(serverId || ''));
  return index >= 0 ? `server${index + 1}` : String(serverId || '');
}

function resolveServerRouteToken(token) {
  const text = String(token || '');
  const match = text.match(/^server(\d+)$/i) || text.match(/^服务器(\d+)$/);
  if (match) {
    const server = overview?.servers?.[Number(match[1]) - 1];
    if (server?.id) return server.id;
  }
  return text;
}

function cssEscape(value) {
  if (window.CSS?.escape) return CSS.escape(String(value));
  return String(value).replace(/["\\]/g, '\\$&');
}

